def parse_grid(block):
    rows=[]
    for line in block.strip().splitlines():
        vals=re.findall(r'\d+',line)
        if len(vals)==11: rows.append(tuple(map(int,vals)))
    return tuple(rows) if len(rows)==16 else None
pairs=[]
for t in user_texts:
